function handleCleanUrlRouting() {
  const path = window.location.pathname.toLowerCase();
  let matchedKey = null;

  for (const key of Object.keys(realPageData)) {
    if (path.includes(key)) {
      matchedKey = key;
      break;
    }
  }

  if (matchedKey && realPageData[matchedKey]) {
    const page = realPageData[matchedKey];
    const titleEl = document.getElementById('vsArticleTitle');
    const bodyEl = document.getElementById('vsArticleBody');
    const pillEl = document.getElementById('vsCategoryPillText');
    const imgWrap = document.getElementById('vsHeroImageWrap');
    const heroImg = document.getElementById('vsHeroImg');

    if (titleEl) titleEl.textContent = page.title;
    if (pillEl) pillEl.textContent = page.pill;
    if (heroImg && page.img) {
      heroImg.src = page.img;
      if (imgWrap) imgWrap.style.display = 'block';
    } else if (imgWrap && !page.img) {
      imgWrap.style.display = 'none';
    }

    if (bodyEl) {
      if (matchedKey === 'risk-calculator') {
        const calcHtml = document.getElementById('calculator') ? document.getElementById('calculator').outerHTML : '';
        bodyEl.innerHTML = page.body + calcHtml;
      } else {
        bodyEl.innerHTML = page.body;
      }
    }
    document.title = page.title + ' | VaultShield';
  }
}

window.addEventListener('DOMContentLoaded', () => {
  calculatePremium();
  handleCleanUrlRouting();
});
